// Application/Services/UserService.cs
using Core.Entities;
using Infrastructure.Repositories;

namespace Application.Services
{
    public class UserService
    {
        private readonly UserRepository _repository;

        public UserService(UserRepository repository)
        {
            _repository = repository;
        }

        public void AddUser(User user)
        {
            if (!user.IsEmailValid())
                throw new Exception("Invalid email address.");

            if (!user.IsAdult())
                throw new Exception("User must be at least 18 years old.");

            _repository.AddUser(user);
        }

        public List<User> GetAllUsers() => _repository.GetAllUsers();

        public User GetUserById(int id)
        {
            var user = _repository.GetUserById(id);
            if (user == null)
                throw new Exception("User not found.");
            return user;
        }

        public void DeleteUser(int id)
        {
            var user = GetUserById(id);
            user.DeactivateUser();
            _repository.UpdateUser(user);
        }

        public void UpdateUserEmail(int id, string newEmail)
        {
            var user = GetUserById(id);
            if (!newEmail.Contains("@"))
                throw new Exception("Invalid email format.");
            user.Email = newEmail;
        }

        public void UpdateUserAddress(int id, string newAddress)
        {
            var user = GetUserById(id);
            user.UpdateAddress(newAddress);
        }

        public void PromoteUserToAdmin(int id)
        {
            var user = GetUserById(id);
            user.Role = "Admin";
        }

        public List<User> GetInactiveUsers()
        {
            return _repository.GetAllUsers().Where(u => !u.IsActive).ToList();
        }
    }
}

namespace Core.Entities
{
    public class User
    {
        public int Id { get; set; }
        public string FirstName { get; set; }
        public string LastName { get; set; }
        public string Email { get; set; }
        public DateTime DateOfBirth { get; set; }
        public string PhoneNumber { get; set; }
        public string Address { get; set; }
        public string Role { get; set; }
        public DateTime RegistrationDate { get; set; }
        public bool IsActive { get; set; }

        public User(int id, string firstName, string lastName, string email, DateTime dateOfBirth, string phoneNumber, string address, string role)
        {
            Id = id;
            FirstName = firstName;
            LastName = lastName;
            Email = email;
            DateOfBirth = dateOfBirth;
            PhoneNumber = phoneNumber;
            Address = address;
            Role = role;
            RegistrationDate = DateTime.Now;
            IsActive = true;
        }

        public string GetFullName() => $"{FirstName} {LastName}";

        public bool IsAdult() => DateTime.Now.Year - DateOfBirth.Year >= 18;

        public int CalculateAge()
        {
            var age = DateTime.Now.Year - DateOfBirth.Year;
            if (DateTime.Now.DayOfYear < DateOfBirth.DayOfYear)
                age--;
            return age;
        }

        public bool IsEmailValid()
        {
            return Email.Contains("@") && Email.Contains(".");
        }

        public void DeactivateUser()
        {
            IsActive = false;
        }

        public void UpdateAddress(string newAddress)
        {
            Address = newAddress;
        }

        public void UpdatePhoneNumber(string newPhoneNumber)
        {
            PhoneNumber = newPhoneNumber;
        }

        public string GetUserDetails()
        {
            return $"ID: {Id}\nName: {GetFullName()}\nEmail: {Email}\nAge: {CalculateAge()}\nRole: {Role}\nActive: {IsActive}\nRegistered On: {RegistrationDate}";
        }

        public override string ToString()
        {
            return $"ID: {Id}, Name: {GetFullName()}, Email: {Email}, Age: {CalculateAge()}, Address: {Address}, Phone: {PhoneNumber}, Role: {Role}, Active: {IsActive}";
        }
    }
}

using Core.Entities;

namespace Infrastructure.Repositories
{
    public class UserRepository
    {
        private readonly List<User> _users = new List<User>();

        public void AddUser(User user)
        {
            if (_users.Any(u => u.Email == user.Email))
                throw new Exception("User with this email already exists.");
            _users.Add(user);
        }

        public List<User> GetAllUsers() => _users;

        public User GetUserById(int id) => _users.FirstOrDefault(u => u.Id == id);

        public void RemoveUser(User user)
        {
            _users.Remove(user);
        }

        public void UpdateUser(User updatedUser)
        {
            var index = _users.FindIndex(u => u.Id == updatedUser.Id);
            if (index >= 0)
                _users[index] = updatedUser;
        }

        public List<User> FindUsersByRole(string role)
        {
            return _users.Where(u => u.Role.Equals(role, StringComparison.OrdinalIgnoreCase)).ToList();
        }

        public int CountActiveUsers()
        {
            return _users.Count(u => u.IsActive);
        }
    }
}

// Tests/UserServiceTests.cs
using Application.Services;
using Core.Entities;
using Infrastructure.Repositories;

namespace Tests
{
    public class UserServiceTests
    {
        public void RunTests()
        {
            var repository = new UserRepository();
            var service = new UserService(repository);

            Console.WriteLine("Running Extended UserService Tests...");

            var validUser = new User(1, "John", "Doe", "john.doe@example.com", new DateTime(1990, 1, 1), "1234567890", "123 Main St", "User");
            var invalidUser = new User(2, "Jane", "Doe", "invalidemail", new DateTime(2010, 1, 1), "0987654321", "456 Elm St", "User");

            try
            {
                service.AddUser(validUser);
                Console.WriteLine("Test Passed: Valid User Added");
            }
            catch (Exception e)
            {
                Console.WriteLine($"Test Failed: {e.Message}");
            }

            try
            {
                service.AddUser(invalidUser);
                Console.WriteLine("Test Failed: Invalid User Should Not Be Added");
            }
            catch (Exception)
            {
                Console.WriteLine("Test Passed: Invalid Email Detected");
            }

            Console.WriteLine("Testing User Deletion...");
            service.DeleteUser(1);
            Console.WriteLine("Test Passed: User Deactivated Successfully");

            Console.WriteLine("Promoting User to Admin...");
            service.PromoteUserToAdmin(1);
            Console.WriteLine("Test Passed: User Promoted to Admin");

            Console.WriteLine("Retrieving Inactive Users...");
            var inactiveUsers = service.GetInactiveUsers();
            Console.WriteLine($"Found {inactiveUsers.Count} inactive users.");
        }
    }
}

using Application.Services;
using Core.Entities;

namespace Web.Controllers
{
    public class UserController
    {
        private readonly UserService _service;

        public UserController(UserService service)
        {
            _service = service;
        }

        public void CreateUser(int id, string firstName, string lastName, string email, DateTime dateOfBirth, string phoneNumber, string address, string role)
        {
            var user = new User(id, firstName, lastName, email, dateOfBirth, phoneNumber, address, role);
            _service.AddUser(user);
        }

        public void DisplayAllUsers()
        {
            var users = _service.GetAllUsers();
            foreach (var user in users)
            {
                Console.WriteLine(user.GetUserDetails());
            }
        }

        public void DeleteUserById(int id)
        {
            _service.DeleteUser(id);
            Console.WriteLine($"User with ID {id} has been deactivated.");
        }

        public void UpdateUserEmail(int id, string newEmail)
        {
            _service.UpdateUserEmail(id, newEmail);
            Console.WriteLine("User email updated successfully.");
        }

        public void PromoteUserToAdmin(int id)
        {
            _service.PromoteUserToAdmin(id);
            Console.WriteLine("User promoted to Admin role.");
        }
    }
}
